/* LOCAL LAB. Same navigation and actions as Emmy's OS; isolated visual experiment. */
window.addEventListener('load',()=>{
let profile=new URLSearchParams(location.search).get('motion')||'cinematic';
if(!['quiet','spatial','cinematic'].includes(profile))profile='cinematic';
let reduce=matchMedia('(prefers-reduced-motion: reduce)').matches, gateUntil=0, launch=null;
const originals={tiles:renderTiles,status:renderStatus,go,activate,focus:setFocus,emo:openEmoRing,closeEmo:closeEmoRing};
const duration=()=>reduce?0:profile==='quiet'?180:profile==='spatial'?320:460;
const E='cubic-bezier(.16,1,.3,1)';
const menu=document.createElement('nav');menu.className='lab-switch';menu.setAttribute('aria-label','Tres propuestas completas');menu.innerHTML='<button id="labHome">← Inicio</button><button data-profile="quiet">01 · Voz</button><button data-profile="spatial">02 · Pulso</button><button data-profile="cinematic">03 · Prisma</button><button id="reduceMotion">Reducir movimiento</button><button id="labTools">Controles</button>';document.body.append(menu);
const note=document.createElement('div');note.className='lab-local';note.textContent='TOKI LAB / SOLO LOCAL';document.body.append(note);
const help=document.createElement('div');help.className='lab-help';help.innerHTML='Mouse + clic o Espacio · <a href="woki-os.html">Abrir original</a><br>Sin puente EMG conectado en este laboratorio.';document.body.append(help);
function syncProfile(){document.body.dataset.motion=profile;document.body.classList.toggle('reduce-motion',reduce);menu.querySelectorAll('[data-profile]').forEach(b=>b.classList.toggle('on',b.dataset.profile===profile));document.querySelector('#reduceMotion').classList.toggle('on',reduce);document.documentElement.style.setProperty('--motion',duration()+'ms');}
menu.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;b.blur();if(b.id==='labHome'){go('home')}else if(b.dataset.profile){profile=b.dataset.profile;history.replaceState(null,'','?motion='+profile);syncProfile();renderTiles();animatePage();}else if(b.id==='reduceMotion'){reduce=!reduce;syncProfile()}else document.body.classList.toggle('lab-debug')});
fit=function(){const s=Math.min((innerWidth-24)/1920,(innerHeight-100)/1080);S.scale=s;const w=document.querySelector('#wrap');w.style.transform=`scale(${s})`;w.style.left=((innerWidth-1920*s)/2)+'px';w.style.top='24px'};addEventListener('resize',fit);
renderStatus=function(){const sc=document.querySelector('.screen.on');const active=window.NOSE?.on;const input=active?(NOSE.mode==='gaze'?'Mirada · cámara':'Cabeza · cámara'):'Mouse · demo';const time=new Date().toTimeString().slice(0,5);document.querySelectorAll('.status').forEach(el=>{const existing=el.querySelector('.nav-home');if(existing&&S.focus===existing)clearFocus();el.innerHTML=`<div class="lab-brand">toki<span>·</span></div>${S.screen!=='home'?'<div class="t nav-home" data-t data-act="go:home">← Inicio</div>':''}<div class="pill"><span class="dot"></span>${input}</div><div class="pill">${CFG.mode==='click'?'Apuntar + confirmar':'Permanencia'}</div><div class="title">${sc?.dataset.title||'Inicio'}</div><div class="clock">${time}</div>`;decorate(el)});document.querySelector('#restClock').textContent=time;};
// Don't re-create navigation under the pointer every clock tick.
let statusKey='';const renderStatusNow=renderStatus;
renderStatus=function(){const key=[S.screen,window.NOSE?.on,window.NOSE?.mode,CFG.mode].join('|');if(key!==statusKey){statusKey=key;renderStatusNow()}document.querySelectorAll('.status .clock').forEach(c=>c.textContent=new Date().toTimeString().slice(0,5));document.querySelector('#restClock').textContent=new Date().toTimeString().slice(0,5)};
renderTiles=function(){originals.tiles();const host=document.querySelector('#tiles');const cells=[...host.children];const positions=[[410,150],[880,75],[1350,150],[1510,415],[1350,680],[880,755],[410,680],[250,415]];
cells.forEach((el,i)=>{el.style.setProperty('--x',(positions[i]||[880,415])[0]);el.style.setProperty('--y',(positions[i]||[880,415])[1]);el.setAttribute('role','button');el.tabIndex=0;el.setAttribute('aria-label',TILES[i][3]);const app=el.querySelector('.app'),ring=el.querySelector(':scope > .ring');if(app&&ring){ring.setAttribute('aria-hidden','true');ring.querySelectorAll('circle').forEach(c=>{c.setAttribute('r','30');c.setAttribute('pathLength','100')});app.append(ring);}});
};
setFocus=function(el){originals.focus(el);if(S.emoRingFor!==null){const id=el?.dataset.act?.split(':')[1];const mid=document.querySelector('#emoC .mid');if(mid&&mid.dataset.preview!==(id||'')){mid.dataset.preview=id||'';mid.innerHTML=EMO[id]?`<span style="font-size:64px">${EMO[id].e}</span><span>${EMO[id].n}</span><small style="font-size:18px;color:#aabbd8">Clic para elegir</small>`:'¿Cómo quieres<br>decirlo?';document.querySelectorAll('.wheel-sector').forEach(p=>p.classList.toggle('selected',p.dataset.emotion===id));}return;}const core=document.querySelector('#homeCore');if(!core)return;const t=el?.classList.contains('tile')?el:null;const label=t?.querySelector('.lb')?.textContent;const desc=t?.querySelector('.sb')?.textContent;const name=core.querySelector('.core-name');if(name.dataset.last===(label||''))return;name.dataset.last=label||'';name.textContent=label||'Tu mundo. A tu ritmo.';core.querySelector('.core-desc').textContent=desc||'Elige lo que quieres hacer.';if(!reduce){name.animate([{opacity:.35},{opacity:1}],{duration:180,easing:'ease-out'});core.querySelector('.core-orb')?.animate([{filter:'brightness(1.2)'},{filter:'brightness(1)'}],{duration:260})}};
function travel(){if(!launch||reduce||profile==='quiet'){launch=null;return}const to=document.querySelector('.screen.on .lab-brand')?.getBoundingClientRect();if(!to)return;const el=document.createElement('div');el.id='travelIcon';el.innerHTML=launch.html;el.style.cssText=`left:${launch.r.left}px;top:${launch.r.top}px;width:${launch.r.width}px;height:${launch.r.height}px;background:${launch.bg}`;document.body.append(el);const dx=to.left-launch.r.left,dy=to.top-launch.r.top;el.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx}px,${dy}px) scale(.25)`,opacity:0}],{duration:duration(),easing:E,fill:'forwards'}).onfinish=()=>el.remove();launch=null;}
go=function(name){const prev=S.screen;originals.go(name);statusKey='';renderStatus();if(prev!==name){gateUntil=performance.now()+duration();const next=document.querySelector('.screen.on');if(!reduce){const sections=[...next.children].filter(el=>!el.classList.contains('status')&&!el.classList.contains('hint'));sections.forEach(el=>el.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:duration(),easing:E}));}travel()}};
activate=function(el,calibrate=true){if(calibrate&&performance.now()<gateUntil)return;const returning=el.dataset.act.startsWith('setEmo:')?{rect:el.getBoundingClientRect(),index:S.emoRingFor,text:EMO[el.dataset.act.split(':')[1]].e}:null;const icon=el.querySelector('.app');if(icon&&el.dataset.act.startsWith('go:'))launch={r:icon.getBoundingClientRect(),html:icon.querySelector('svg:not(.ring)').outerHTML,bg:getComputedStyle(icon).background};if(!reduce){const wave=document.createElement('span');wave.className='confirm-wave';(icon||el).append(wave);setTimeout(()=>wave.remove(),500)}originals.activate(el,calibrate);if(returning&&!reduce){const dest=document.querySelector(`[data-act="emo:${returning.index}"]`);if(dest){const r=dest.getBoundingClientRect(),echo=document.createElement('div');echo.className='echo-emoji';echo.textContent=returning.text;echo.style.cssText=`position:fixed;left:${returning.rect.left}px;top:${returning.rect.top}px;width:${returning.rect.width}px;height:${returning.rect.height}px;display:grid;place-items:center;font-size:48px;z-index:110;pointer-events:none`;document.body.append(echo);echo.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${r.left-returning.rect.left}px,${r.top-returning.rect.top}px) scale(.45)`,opacity:0}],{duration:duration(),easing:E}).onfinish=()=>echo.remove();}}};
openEmoRing=function(i){originals.emo(i);const c=document.querySelector('#emoC');const mid=c.querySelector('.mid');if(mid)mid.innerHTML='¿Cómo quieres<br>decirlo?';const petals=[...c.querySelectorAll('[data-t]')];
const polar=(r,a)=>[500+r*Math.cos(a*Math.PI/180),475+r*Math.sin(a*Math.PI/180)];
let arcs=EMOS.map((e,k)=>{const a=-90+k*60;const p1=polar(210,a-27),p2=polar(410,a-27),p3=polar(410,a+27),p4=polar(210,a+27);return `<path class="wheel-sector" data-emotion="${e.id}" d="M${p1} L${p2} A410 410 0 0 1 ${p3} L${p4} A210 210 0 0 0 ${p1} Z"/>`}).join('');
c.insertAdjacentHTML('afterbegin',`<svg class="wheel-back" viewBox="0 0 1000 950" aria-hidden="true">${arcs}</svg>`);gateUntil=performance.now()+duration();if(!reduce)petals.forEach(el=>{const dx=500-parseFloat(el.style.left)*10;const dy=475-parseFloat(el.style.top)*9.5;el.animate([{opacity:0,transform:`translate(${dx*.28}px,${dy*.28}px) scale(.78)`},{opacity:1,transform:'translate(0,0) scale(1)'}],{duration:duration(),easing:E})});};
// Restore always-available exits; the original keeps keyboard/gesture paths as well.
const exit=document.createElement('button');exit.className='lab-switch';exit.style.cssText='left:auto;right:25px;bottom:100px;transform:none;padding:14px 25px;color:#e0eafa;cursor:pointer;display:none';exit.textContent='← Volver';document.body.append(exit);exit.onclick=()=>{if(S.emoRingFor!==null)closeEmoRing();else if(S.rest)setRest(false);else if(S.alarm)stopAlarm('Demo finalizada');};
const obs=new MutationObserver(()=>{exit.style.display=S.emoRingFor!==null||S.rest||document.querySelector('#alarm').classList.contains('on')?'block':'none'});['emoRing','rest','alarm'].forEach(id=>obs.observe(document.getElementById(id),{attributes:true,attributeFilter:['class']}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#calib').classList.contains('on')){if(S.emoRingFor!==null)closeEmoRing();else if(S.rest)setRest(false);else if(!S.alarm)go('home')}if(e.key==='Enter'&&e.target.matches('[data-t]')){e.preventDefault();activate(e.target,false)}});
// Context-matching hints, no new gesture vocabulary.
document.querySelector('#s-home .hint').innerHTML='<span>Apunta a una opción · <b>Clic o Espacio para entrar</b></span>';
document.querySelector('#s-talk .hint').innerHTML='<span><b>Frase</b> para hablar · <b>Emoji</b> para abrir el selector de tono</span>';
for(const [id,hint] of Object.entries({reactions:'Elige una reacción para decirla · Más para ver otras',keyboard:'Elige un grupo y después una letra · Inicio para volver',agent:'Demostración · confirma dos veces para simular el envío',settings:'Elige un ajuste para cambiarlo'}))document.querySelector('#s-'+id+' .hint').innerHTML='<span>'+hint+'</span>';
document.querySelector('#rest .sub').textContent='Descansando · Volver o Escape para continuar';
// Keep the copied flow's optional camera calibration available via Controls.
CAL.close();syncProfile();renderTiles();renderStatus();fit();
const lines=document.createElementNS('http://www.w3.org/2000/svg','svg');lines.classList.add('scene-lines');lines.setAttribute('viewBox','0 0 1920 1080');lines.setAttribute('aria-hidden','true');lines.innerHTML='<path d="M-300 1000 Q650 -300 2200 450 M-300 1030 Q650 -270 2200 480 M-300 1060 Q650 -240 2200 510 M-300 1090 Q650 -210 2200 540 M-300 1120 Q650 -180 2200 570"/><circle cx="1800" cy="-50" r="600"/><circle cx="1800" cy="-50" r="620"/>';document.querySelector('#stage').prepend(lines);
function animatePage(){if(reduce)return;const targets=document.querySelectorAll('.screen.on .tile,.screen.on .card,.screen.on .react,.screen.on .key,.screen.on .set,.screen.on .btn');gateUntil=performance.now()+600;targets.forEach((el,i)=>el.animate(profile==='quiet'?[{opacity:0,transform:'translateX(-35px)'},{opacity:1,transform:'translateX(0)'}]:profile==='spatial'?[{opacity:0,transform:'scale(.85)'},{opacity:1,transform:'scale(1)'}]:[{opacity:0,transform:'perspective(900px) rotateX(12deg) translateY(50px)'},{opacity:1,transform:'perspective(900px) rotateX(0) translateY(0)'}],{duration:420,delay:i*22,easing:E,fill:'backwards'}));lines.animate([{transform:'translateX(-45px)',opacity:0},{transform:'translateX(0)',opacity:.14}],{duration:650,easing:E})}
const previousGo=go;go=function(name){previousGo(name);requestAnimationFrame(animatePage)};
const oldReactions=renderReacts;renderReacts=function(){oldReactions();document.querySelectorAll('#reacts .react').forEach(el=>{el.setAttribute('role','button');el.tabIndex=0;});requestAnimationFrame(animatePage)};
const oldKeys=renderKeys;renderKeys=function(){oldKeys();requestAnimationFrame(animatePage)};
const oldCards=renderCards;renderCards=function(){oldCards();requestAnimationFrame(animatePage)};
const sceneLabel=document.createElement('div');sceneLabel.className='scene-label';sceneLabel.textContent='Exploración de escritorio · v3';document.body.append(sceneLabel);
animatePage();
window.TOKI_MOTION_LAB={get profile(){return profile},get reduce(){return reduce},get gateUntil(){return gateUntil}};
});
